import sys
from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    ptr = 0
    n = int(input[ptr])
    ptr += 1
    m = int(input[ptr])
    ptr += 1
    grid = []
    for _ in range(n):
        row = list(map(int, input[ptr:ptr + m]))
        ptr += m
        grid.append(row)

    max_val = n * m
    pos = [[0] * (max_val + 2) for _ in range(2)]
    for i in range(n):
        for j in range(m):
            val = grid[i][j]
            pos[0][val] = i
            pos[1][val] = j

    parent = [0] * (max_val + 2)
    size = [1] * (max_val + 2)
    res = 0

    for r in range(1, max_val + 1):
        for l in range(r, 0, -1):
            x1, y1 = pos[0][l], pos[1][l]
            x2, y2 = pos[0][r], pos[1][r]
            if x1 == x2 and abs(y1 - y2) == r - l:
                continue
            if y1 == y2 and abs(x1 - x2) == r - l:
                continue
            if abs(x1 - x2) + abs(y1 - y2) != r - l:
                continue
            if parent[l] == 0:
                parent[l] = r
                size[r] += size[l]
                res += 1
            else:
                if parent[l] == r:
                    res += 1
                else:
                    break
        else:
            continue
        break

    print(res)

if __name__ == '__main__':
    main()
